#include "rsm_test_hal.h"
#include <string.h>
static uint64_t tm(void*c){return ((rsm_test_hal_t*)c)->time_us;}static rsm_status_t rd(void*c,uint32_t i,rsm_value_t*v){rsm_test_hal_t*h=c;h->reads++;if(h->fail_read||i>=RSM_TEST_ENDPOINTS)return RSM_STATUS_HAL_ERROR;if(h->input_valid[i])*v=h->inputs[i];return RSM_STATUS_OK;}static rsm_status_t wr(void*c,uint32_t i,const rsm_value_t*v){rsm_test_hal_t*h=c;h->writes++;if(h->fail_write||i>=RSM_TEST_ENDPOINTS)return RSM_STATUS_HAL_ERROR;h->outputs[i]=*v;h->output_valid[i]=1;return RSM_STATUS_OK;}static rsm_status_t kick(void*c){rsm_test_hal_t*h=c;h->kicks++;return h->fail_watchdog?RSM_STATUS_HAL_ERROR:RSM_STATUS_OK;}
void rsm_test_hal_init(rsm_test_hal_t*h,rsm_hal_t*v){memset(h,0,sizeof *h);memset(v,0,sizeof *v);v->monotonic_time_us=tm;v->read_input=rd;v->write_output=wr;v->kick_watchdog=kick;}void rsm_test_hal_set_time_us(rsm_test_hal_t*h,uint64_t t){h->time_us=t;}void rsm_test_hal_advance_time_us(rsm_test_hal_t*h,uint64_t d){h->time_us+=d;}rsm_status_t rsm_test_hal_set_input(rsm_test_hal_t*h,uint32_t i,const rsm_value_t*v){if(!h||!v||i>=RSM_TEST_ENDPOINTS)return RSM_STATUS_INVALID_ARGUMENT;h->inputs[i]=*v;h->input_valid[i]=1;return RSM_STATUS_OK;}rsm_status_t rsm_test_hal_get_output(const rsm_test_hal_t*h,uint32_t i,rsm_value_t*v){if(!h||!v||i>=RSM_TEST_ENDPOINTS||!h->output_valid[i])return RSM_STATUS_INVALID_ARGUMENT;*v=h->outputs[i];return RSM_STATUS_OK;}
